import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Buenas practicas de GitHub Actions","description":"","frontmatter":{},"headers":[],"relativePath":"cloud/github-actions/08-buenas-practicas.md","filePath":"cloud/github-actions/08-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),r={name:"cloud/github-actions/08-buenas-practicas.md"};function n(s,e,l,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="buenas-practicas-de-github-actions" tabindex="-1">Buenas practicas de GitHub Actions <a class="header-anchor" href="#buenas-practicas-de-github-actions" aria-label="Permalink to &quot;Buenas practicas de GitHub Actions&quot;">​</a></h1><p>Recomendaciones transversales para mantener workflows rapidos, seguros y faciles de evolucionar.</p><h2 id="diseno-de-workflows" tabindex="-1">Diseno de workflows <a class="header-anchor" href="#diseno-de-workflows" aria-label="Permalink to &quot;Diseno de workflows&quot;">​</a></h2><ul><li><strong>Un proposito por workflow</strong> — <code>ci.yml</code>, <code>deploy.yml</code>, <code>nightly.yml</code>.</li><li><strong>Nombres claros</strong> en workflows, jobs y steps.</li><li><strong>Comentarios</strong> en cron y condiciones <code>if</code> no obvias.</li><li><strong>DRY</strong> con composite actions y <code>workflow_call</code>.</li><li><strong>Paths filters</strong> para no gastar minutos en cambios irrelevantes.</li></ul><h2 id="rendimiento-y-coste" tabindex="-1">Rendimiento y coste <a class="header-anchor" href="#rendimiento-y-coste" aria-label="Permalink to &quot;Rendimiento y coste&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tecnica</th><th>Beneficio</th></tr></thead><tbody><tr><td>Cache npm/pip</td><td>Menos tiempo de install</td></tr><tr><td><code>fail-fast</code> estrategico</td><td>Feedback rapido en PR</td></tr><tr><td>Jobs paralelos</td><td>Menor wall-clock time</td></tr><tr><td>Self-hosted selectivo</td><td>GPUs / red interna</td></tr><tr><td><code>concurrency</code> + cancel</td><td>Evita colas duplicadas</td></tr></tbody></table><p>Revisa Usage en Settings -&gt; Billing para detectar workflows caros.</p><h2 id="seguridad-resumen" tabindex="-1">Seguridad (resumen) <a class="header-anchor" href="#seguridad-resumen" aria-label="Permalink to &quot;Seguridad (resumen)&quot;">​</a></h2><ul><li><code>permissions</code> minimas explicitas.</li><li>Secrets en environments con aprobacion para prod.</li><li>OIDC a cloud en lugar de keys estaticas.</li><li>Pin de versions en <code>uses:</code>.</li><li>Cuidado con <code>pull_request_target</code> y scripts de forks.</li><li>Dependabot para actions y dependencias.</li></ul><h2 id="mantenibilidad" tabindex="-1">Mantenibilidad <a class="header-anchor" href="#mantenibilidad" aria-label="Permalink to &quot;Mantenibilidad&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.github/</span></span>
<span class="line"><span>  workflows/       # orquestacion</span></span>
<span class="line"><span>  actions/         # composite reutilizables</span></span>
<span class="line"><span>  CODEOWNERS       # quien aprueba cambios en CI</span></span></code></pre></div><ul><li>Versiona cambios de pipeline como codigo de aplicacion.</li><li>Documenta en README como reejecutar workflows y interpretar fallos.</li><li>Alerta si <code>main</code> queda rojo (integracion Slack/email).</li></ul><h2 id="observabilidad" tabindex="-1">Observabilidad <a class="header-anchor" href="#observabilidad" aria-label="Permalink to &quot;Observabilidad&quot;">​</a></h2><ul><li>Badges en README: <code>![CI](https://github.com/org/repo/actions/workflows/ci.yml/badge.svg)</code></li><li>Annotations con <code>::error</code> / <code>::warning</code> en scripts.</li><li>Retencion de logs y artefactos acorde a compliance.</li><li>Enlazar commit -&gt; deployment en environments de GitHub.</li></ul><h2 id="testing-del-propio-ci" tabindex="-1">Testing del propio CI <a class="header-anchor" href="#testing-del-propio-ci" aria-label="Permalink to &quot;Testing del propio CI&quot;">​</a></h2><ul><li>PR que rompe lint debe fallar el workflow (prueba una vez al configurar).</li><li>Workflow <code>workflow_dispatch</code> para probar deploy sin merge.</li><li>Branch de prueba antes de tocar prod deploy.</li></ul><h2 id="integracion-con-el-ecosistema" tabindex="-1">Integracion con el ecosistema <a class="header-anchor" href="#integracion-con-el-ecosistema" aria-label="Permalink to &quot;Integracion con el ecosistema&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Necesidad</th><th>Recurso</th></tr></thead><tbody><tr><td>Principios CI/CD</td><td><a href="./../../devops/cicd/01-introduccion-y-principios">CI/CD</a></td></tr><tr><td>Contenedores</td><td><a href="./../../herramientas/docker/14-ci-cd-con-docker">Docker</a></td></tr><tr><td>Kubernetes</td><td><a href="./../kubernetes/12-gitops-y-ci-cd">Kubernetes</a></td></tr><tr><td>Terraform</td><td><a href="./../../devops/terraform/01-introduccion-e-instalacion">Terraform</a></td></tr></tbody></table><h2 id="checklist-de-madurez" tabindex="-1">Checklist de madurez <a class="header-anchor" href="#checklist-de-madurez" aria-label="Permalink to &quot;Checklist de madurez&quot;">​</a></h2><h3 id="basico" tabindex="-1">Basico <a class="header-anchor" href="#basico" aria-label="Permalink to &quot;Basico&quot;">​</a></h3><ul><li>[ ] CI en cada PR</li><li>[ ] Checkout + setup + test + build</li><li>[ ] Secrets fuera del repo</li></ul><h3 id="intermedio" tabindex="-1">Intermedio <a class="header-anchor" href="#intermedio" aria-label="Permalink to &quot;Intermedio&quot;">​</a></h3><ul><li>[ ] Cache de dependencias</li><li>[ ] Artefactos entre jobs</li><li>[ ] Deploy staging en main</li><li>[ ] Branch protection con required checks</li></ul><h3 id="avanzado" tabindex="-1">Avanzado <a class="header-anchor" href="#avanzado" aria-label="Permalink to &quot;Avanzado&quot;">​</a></h3><ul><li>[ ] Matrices de compatibilidad</li><li>[ ] OIDC a cloud</li><li>[ ] Environments con aprobacion</li><li>[ ] Workflows reutilizables en monorepo</li><li>[ ] Docker layer cache (GHA)</li></ul><h2 id="errores-que-frenan-equipos" tabindex="-1">Errores que frenan equipos <a class="header-anchor" href="#errores-que-frenan-equipos" aria-label="Permalink to &quot;Errores que frenan equipos&quot;">​</a></h2><ul><li>Workflows de 40 min que nadie optimiza.</li><li>Copiar YAML de internet sin entender permissions.</li><li>Secrets compartidos entre todos los entornos.</li><li>No actualizar actions deprecadas hasta que fallan.</li><li>CI verde en PR pero deploy manual sin automatizar ni documentar.</li></ul><h2 id="cierre" tabindex="-1">Cierre <a class="header-anchor" href="#cierre" aria-label="Permalink to &quot;Cierre&quot;">​</a></h2><p>GitHub Actions es la capa de automatizacion mas accesible si ya usas GitHub. Invierte en pipelines pequenos, seguros y rapidos; reutiliza patrones de este manual y de <a href="./../../devops/cicd/07-buenas-practicas">CI/CD</a> para cerrar el ciclo hasta produccion.</p><p>Este repositorio aplica practicas concretas: validacion en PR, deploy documentado y permisos acotados por workflow.</p>`,30)])])}const b=a(r,[["render",n]]);export{h as __pageData,b as default};
